<?php
require_once 'config/config.php';require_once 'includes/functions.php';require_login();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if($action==='issue'){$book=(int)($_POST['book_id']??0);$member=(int)($_POST['member_id']??0);$days=max(1,min(90,(int)($_POST['loan_days']??setting($pdo,'loan_days','14'))));
 try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM books WHERE id=? FOR UPDATE");$s->execute([$book]);$b=$s->fetch();$m=$pdo->prepare("SELECT * FROM members WHERE id=? AND status='Active'");$m->execute([$member]);$mem=$m->fetch();
 if(!$b||$b['available_copies']<1||!$mem)throw new RuntimeException('Selected book is unavailable or member is inactive.');
 $pdo->prepare("INSERT INTO loans(book_id,member_id,issue_date,due_date,issued_by) VALUES(?,?,CURDATE(),DATE_ADD(CURDATE(), INTERVAL ? DAY),?)")->execute([$book,$member,$days,$_SESSION['admin_id']]);
 $pdo->prepare('UPDATE books SET available_copies=available_copies-1 WHERE id=?')->execute([$book]);$pdo->commit();flash('Book issued successfully.');}
 catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Unable to issue book.','error');}redirect('issue.php');}
 if($action==='return'){$id=(int)$_POST['loan_id'];try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM loans WHERE id=? AND status='Issued' FOR UPDATE");$s->execute([$id]);$l=$s->fetch();if(!$l)throw new RuntimeException('This loan is already returned or does not exist.');
 $finePerDay=(float)setting($pdo,'fine_per_day','5');$pdo->prepare("UPDATE loans SET return_date=CURDATE(),status='Returned',fine_amount=GREATEST(DATEDIFF(CURDATE(),due_date),0)*? WHERE id=?")->execute([$finePerDay,$id]);$fineQ=$pdo->prepare('SELECT fine_amount FROM loans WHERE id=?');$fineQ->execute([$id]);$finalFine=(float)$fineQ->fetchColumn();$pdo->prepare('UPDATE books SET available_copies=available_copies+1 WHERE id=?')->execute([$l['book_id']]);$pdo->commit();flash('Book returned successfully. Fine: '.money($finalFine));}
 catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Unable to process return.','error');}redirect('issue.php');}
}
$books=$pdo->query("SELECT id,title,author,available_copies FROM books WHERE available_copies>0 ORDER BY title")->fetchAll();$members=$pdo->query("SELECT id,member_code,name FROM members WHERE status='Active' ORDER BY name")->fetchAll();
$loans=$pdo->query("SELECT l.*,b.title,m.name member_name,m.member_code FROM loans l JOIN books b ON b.id=l.book_id JOIN members m ON m.id=l.member_id WHERE l.status='Issued' ORDER BY l.due_date")->fetchAll();
$page_title='Issue and Return';require 'includes/header.php';?>
<div class="page-heading"><div><p class="eyebrow">CIRCULATION DESK</p><h1>Issue & return</h1><p class="muted">Record book loans, process returns and calculate late fines.</p></div></div>
<div class="content-grid"><section class="panel form-panel"><h2>Issue a book</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="issue"><div class="field"><label>Select book *</label><select name="book_id" required><option value="">Choose available book</option><?php foreach($books as $b):?><option value="<?=$b['id']?>"><?=e($b['title'])?> — <?=$b['available_copies']?> available</option><?php endforeach;?></select></div><div class="field"><label>Select member *</label><select name="member_id" required><option value="">Choose active member</option><?php foreach($members as $m):?><option value="<?=$m['id']?>"><?=e($m['member_code'].' · '.$m['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Loan period (days)</label><input type="number" name="loan_days" min="1" max="90" value="<?=e(setting($pdo,'loan_days','14'))?>"></div><button class="btn primary">Confirm issue</button></form><p class="hint">Default late fine: <?=money(setting($pdo,'fine_per_day','5'))?> per day.</p></section>
<section class="panel"><div class="panel-heading"><h2>Currently issued <span class="count"><?=count($loans)?></span></h2></div><div class="table-wrap"><table><thead><tr><th>Book / member</th><th>Issue date</th><th>Due date</th><th>Late fine today</th><th>Action</th></tr></thead><tbody><?php foreach($loans as $l):$late=max(0,(int)((strtotime(date('Y-m-d'))-strtotime($l['due_date']))/86400));$fine=$late*(float)setting($pdo,'fine_per_day','5');?><tr><td><b><?=e($l['title'])?></b><small><?=e($l['member_code'].' · '.$l['member_name'])?></small></td><td><?=e($l['issue_date'])?></td><td><?=e($l['due_date'])?></td><td><?=money($fine)?></td><td><form method="post" onsubmit="return confirm('Confirm book return?')"><?=csrf_field()?><input type="hidden" name="action" value="return"><input type="hidden" name="loan_id" value="<?=$l['id']?>"><button class="btn small primary">Return</button></form></td></tr><?php endforeach;?><?php if(!$loans):?><tr><td colspan="5" class="empty">There are no active loans.</td></tr><?php endif;?></tbody></table></div></section></div>
<?php require 'includes/footer.php';?>
